# SPDX-License-Identifier: Apache-2.0
"""Emit checked-in Rust bindings. Run from the repository root with make generate."""

import json
from pathlib import Path
import subprocess
import sys
from typing import cast

from clients import render_group
from declarations import render_declaration
from schema import Declaration, Rpc, calls_from_json, declarations_from_json
from parity import generate_parity
from versioning import synchronize_version

HEADER = (
    "// SPDX-License-Identifier: Apache-2.0\n"
    "// Generated by scripts/rustgen; edit the Go contract and run make generate.\n"
    "// Preserve Go signatures and nullable collection layers at this language boundary.\n"
    "#![allow(clippy::type_complexity, clippy::too_many_arguments)]\n\n"
)


def write_chunks(directory: Path, chunks: list[str]) -> list[str]:
    directory.mkdir(parents=True, exist_ok=True)
    for old in directory.glob("bindings_*.rs"):
        old.unlink()
    files: list[str] = []
    content = ""
    marker = "// RUSTGEN-DECLARATION-BOUNDARY\n"
    formatted = subprocess.run(
        ["rustfmt", "--edition", "2024"],
        input=marker.join(chunks),
        text=True,
        capture_output=True,
        check=True,
    ).stdout
    for chunk in formatted.split(marker):
        if len((content + chunk).splitlines()) > 460 and content:
            files.append(write_chunk(directory, len(files), content))
            content = ""
        content += chunk + "\n"
    if content:
        files.append(write_chunk(directory, len(files), content))
    return files


def write_chunk(directory: Path, index: int, content: str) -> str:
    name = f"bindings_{index:03}"
    (directory / f"{name}.rs").write_text(HEADER + content)
    return name


def write_module(directory: Path, chunks: list[str], additions: str = "") -> None:
    modules = write_chunks(directory, chunks)
    exports = "".join(f"mod {name};\npub use {name}::*;\n" for name in modules)
    (directory / "mod.rs").write_text(HEADER + exports + additions)


def generate_values(
    root: Path, declarations: list[Declaration], interfaces: set[tuple[str, str]]
) -> None:
    for package in ("types", "contract", "wire", "featureargs"):
        directory = root / ("wire/featureargs" if package == "featureargs" else package)
        chunks = [
            render_declaration(item, interfaces)
            for item in declarations
            if item.package == package
        ]
        additions = "pub mod featureargs;\n" if package == "wire" else ""
        if package == "types":
            additions += "mod geometry;\npub use geometry::*;\nmod variant;\npub use variant::*;\n"
        write_module(directory, chunks, additions)


def generate_clients(
    root: Path, calls: list[Rpc], interfaces: set[tuple[str, str]]
) -> None:
    groups = sorted({call.group for call in calls})
    chunks: list[str] = []
    for group in groups:
        methods = [call for call in calls if call.group == group]
        chunks.extend(
            render_group(group, methods[index : index + 16], interfaces, index == 0)
            for index in range(0, len(methods), 16)
        )
    write_module(
        root / "client",
        chunks,
        "mod transport;\npub use transport::*;\nmod host;\npub use host::HostTransport;\nmod features;\n",
    )


def generate_bindings(schema: dict[str, object], root: Path) -> None:
    declarations = declarations_from_json(schema)
    interfaces = {
        (item.package, item.name)
        for item in declarations
        if item.shape.kind == "interface"
    }
    interfaces.update(
        (item.package, item.name)
        for item in declarations
        if item.alias and (item.shape.package, item.shape.name) in interfaces
    )
    calls = calls_from_json(schema)
    validate_calls(declarations, calls)
    generate_values(root, declarations, interfaces)
    generate_clients(root, calls, interfaces)
    generate_parity(declarations, calls, interfaces)
    print(f"Generated {len(declarations)} declarations and {len(calls)} typed calls.")


def validate_calls(declarations: list[Declaration], calls: list[Rpc]) -> None:
    methods = {
        item.name
        for item in declarations
        if item.package == "wire" and item.name.startswith("Method")
    }
    missing = methods - {call.method for call in calls}
    if missing:
        raise ValueError(
            f"{sorted(missing)}: expected a typed client for every wire method"
        )


def main() -> None:
    synchronize_version(Path("."))
    source = json.loads(sys.stdin.read())
    generate_bindings(cast(dict[str, object], source), Path("rust/src"))


if __name__ == "__main__":
    main()
